package com.yatima.model; import jakarta.persistence.*;
@Entity public class Donation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String donorName,donorPhone,orphanName,paymentMethod="PBZ",status="PENDING",institutionName,institutionPbzAccount,institutionPbzName; private Long orphanId,amount;
public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getDonorName(){return donorName;} public void setDonorName(String n){this.donorName=n;} public String getDonorPhone(){return donorPhone;} public void setDonorPhone(String p){this.donorPhone=p;} public Long getOrphanId(){return orphanId;} public void setOrphanId(Long id){this.orphanId=id;} public String getOrphanName(){return orphanName;} public void setOrphanName(String n){this.orphanName=n;} public Long getAmount(){return amount;} public void setAmount(Long a){this.amount=a;} public String getPaymentMethod(){return paymentMethod;} public void setPaymentMethod(String m){this.paymentMethod=m;} public String getStatus(){return status;} public void setStatus(String s){this.status=s;} public String getInstitutionName(){return institutionName;} public void setInstitutionName(String n){this.institutionName=n;} public String getInstitutionPbzAccount(){return institutionPbzAccount;} public void setInstitutionPbzAccount(String a){this.institutionPbzAccount=a;} public String getInstitutionPbzName(){return institutionPbzName;} public void setInstitutionPbzName(String n){this.institutionPbzName=n;} }

